  MESSAGES.en.wc_def_N = "Names a person, place, thing or idea (teacher, river, happiness). Proper nouns are the names of particular people or places and start with a capital letter (Nam, Ho Chi Minh City)."; MESSAGES.vi.wc_def_N = "Chỉ người, vật, nơi chốn hay khái niệm (teacher, river, happiness). Danh từ riêng là tên riêng của người, nơi chốn…, viết hoa chữ cái đầu (Nam, Ho Chi Minh City)."; MESSAGES.ko.wc_def_N = "사람, 사물, 장소, 개념을 나타내요 (teacher, river, happiness). 고유 명사는 특정 사람이나 장소의 이름이며 대문자로 시작해요 (Nam, Ho Chi Minh City).";
  MESSAGES.en.wc_def_V = "Shows an action or a state (run, write, believe)."; MESSAGES.vi.wc_def_V = "Chỉ hành động hoặc trạng thái (run, write, believe)."; MESSAGES.ko.wc_def_V = "동작이나 상태를 나타내요 (run, write, believe).";
  MESSAGES.en.wc_def_AuxV = "Goes with the main verb to show tense, mood or voice: be, have, do and modals such as can, will, must (She is reading. I can swim.)."; MESSAGES.vi.wc_def_AuxV = "Đi kèm động từ chính để chỉ thì, thể hoặc khả năng: be, have, do và can, will, must… (She is reading. I can swim.)."; MESSAGES.ko.wc_def_AuxV = "본동사와 함께 시제, 서법, 태를 나타내요: be, have, do와 can, will, must 같은 조동사 (She is reading. I can swim.).";
  MESSAGES.en.wc_def_Adj = "Describes a noun (an old bridge, the sky is blue)."; MESSAGES.vi.wc_def_Adj = "Bổ nghĩa cho danh từ, chỉ tính chất, đặc điểm (an old bridge, the sky is blue)."; MESSAGES.ko.wc_def_Adj = "명사를 꾸미거나 설명해요 (an old bridge, the sky is blue).";
  MESSAGES.en.wc_def_Adv = "Modifies a verb, an adjective or another adverb: how, when, where or how much (finally, very, often, there)."; MESSAGES.vi.wc_def_Adv = "Bổ nghĩa cho động từ, tính từ hoặc trạng từ khác: cách thức, thời gian, nơi chốn, mức độ (finally, very, often, there)."; MESSAGES.ko.wc_def_Adv = "동사, 형용사, 다른 부사를 꾸며 방법, 때, 장소, 정도를 나타내요 (finally, very, often, there).";
  MESSAGES.en.wc_def_Pron = "Takes the place of a noun (I, she, it, who); possessives such as his and her count as pronouns here."; MESSAGES.vi.wc_def_Pron = "Thay thế cho danh từ (I, she, it, who); từ sở hữu như his, her cũng tính là đại từ ở đây."; MESSAGES.ko.wc_def_Pron = "명사를 대신해요 (I, she, it, who). 여기서는 his, her 같은 소유격도 대명사로 봐요.";
  MESSAGES.en.wc_def_Det = "Comes before a noun to say which one or how many (the, a, this, every, some)."; MESSAGES.vi.wc_def_Det = "Đứng trước danh từ để xác định hoặc chỉ số lượng (the, a, this, every, some)."; MESSAGES.ko.wc_def_Det = "명사 앞에서 어느 것인지, 얼마나인지를 나타내요 (the, a, this, every, some).";
  MESSAGES.en.wc_def_Prep = "Links a noun or pronoun to the rest of the sentence, often showing place, time or direction (in, near, before)."; MESSAGES.vi.wc_def_Prep = "Nối danh từ, đại từ với phần còn lại của câu, thường chỉ nơi chốn, thời gian, hướng (in, near, before)."; MESSAGES.ko.wc_def_Prep = "명사나 대명사를 문장의 다른 부분과 이어 주며 주로 장소, 시간, 방향을 나타내요 (in, near, before).";
  MESSAGES.en.wc_def_Conj = "Joins words or clauses. Coordinating: and, but, or (two equal parts). Subordinating: because, if, when (starts a dependent clause)."; MESSAGES.vi.wc_def_Conj = "Nối từ hoặc mệnh đề. Liên từ kết hợp: and, but, or (nối hai phần ngang nhau). Liên từ phụ thuộc: because, if, when (mở đầu mệnh đề phụ)."; MESSAGES.ko.wc_def_Conj = "단어나 절을 이어 줘요. 등위 접속사: and, but, or (대등한 두 부분). 종속 접속사: because, if, when (종속절을 이끌어요).";
  MESSAGES.en.wc_def_Num = "Expresses a number (one, two, 1952)."; MESSAGES.vi.wc_def_Num = "Chỉ số lượng, con số (one, two, 1952)."; MESSAGES.ko.wc_def_Num = "수를 나타내요 (one, two, 1952).";
  MESSAGES.en.wc_def_Part = "A small function word: not / n't, to before a verb (to watch) and the possessive 's (City’s)."; MESSAGES.vi.wc_def_Part = "Từ chức năng nhỏ: not / n't, to đứng trước động từ (to watch) và 's sở hữu (City’s)."; MESSAGES.ko.wc_def_Part = "작은 기능어예요: not / n't, 동사 앞의 to (to watch), 소유를 나타내는 's (City’s).";
